    ],
    // 1206 (3216 metric): pad_span=3.4mm, pad=1.15×1.8mm
    '1206': [
      { number: '1', x_nm: -1_700_000, y_nm: 0, width_nm: 1_150_000, height_nm: 1_800_000, shape: 'rect', layer_mask: 1, drill_nm: null },
