### Initialize and Render Three.js Scene with GLTF Dispersion Model (JavaScript)

Source: https://github.com/mrdoob/three.js/blob/dev/examples/webgl_loader_gltf_dispersion.html

This JavaScript code initializes a Three.js WebGL scene, sets up a perspective camera, WebGL renderer, and OrbitControls. It loads a GLTF model ('models/gltf/DispersionTest.glb') using GLTFLoader, applies a room environment for realistic lighting, and renders the scene. The example specifically integrates the KHR_materials_dispersion extension for realistic material effects and includes window resize handling.

```javascript
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

let camera, scene, renderer;

init().then( render );

async function init() {
  const container = document.createElement( 'div' );
  document.body.appendChild( container );

  camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.01, 5 );
  camera.position.set( 0.1, 0.05, 0.15 );

  scene = new THREE.Scene();

  renderer = new THREE.WebGLRenderer( { antialias: true } );
  renderer.setPixelRatio( window.devicePixelRatio );
  renderer.setSize( window.innerWidth, window.innerHeight );
  renderer.toneMapping = THREE.NeutralToneMapping;
  renderer.toneMappingExposure = 1;
  container.appendChild( renderer.domElement );

  const environment = new RoomEnvironment();
  const pmremGenerator = new THREE.PMREMGenerator( renderer );

  scene = new THREE.Scene();
  scene.backgroundBlurriness = 0.5;

  const env = pmremGenerator.fromScene( environment, 0.04 ).texture;
  scene.background = env;
  scene.environment = env;
  environment.dispose();

  const loader = new GLTFLoader();
  const gltf = await loader.loadAsync( 'models/gltf/DispersionTest.glb' );
  scene.add( gltf.scene );

  const controls = new OrbitControls( camera, renderer.domElement );
  controls.addEventListener( 'change', render ); // use if there is no animation loop
  controls.minDistance = 0.1;
  controls.maxDistance = 10;
  controls.target.set( 0, 0, 0 );
  controls.update();

  window.addEventListener( 'resize', onWindowResize );
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize( window.innerWidth, window.innerHeight );
  render();
}

