### Initialize Three.js Scene with GLTF Sheen Model and Orbit Controls

Source: https://github.com/mrdoob/three.js/blob/dev/examples/webgl_loader_gltf_sheen.html

This JavaScript code initializes a Three.js 3D scene, including a perspective camera, WebGL renderer, and OrbitControls for navigation. It loads a GLTF model ('SheenChair.glb') that utilizes the KHR_materials_sheen extension, adds it to the scene, and integrates a lil-gui panel to control the 'sheen' property of the model's material. The scene also incorporates environment lighting for realistic rendering.

```javascript
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let camera, scene, renderer, controls;

init();

function init() {
	const container = document.createElement( 'div' );
	document.body.appendChild( container );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.1, 20 );
	camera.position.set( - 0.75, 0.7, 1.25 );

	scene = new THREE.Scene();

	// model
	new GLTFLoader()
		.setPath( 'models/gltf/' )
		.load( 'SheenChair.glb', function ( gltf ) {

			scene.add( gltf.scene );

			const object = gltf.scene.getObjectByName( 'SheenChair_fabric' );

			const gui = new GUI();
			gui.add( object.material, 'sheen', 0, 1 );
