            shape: PadShape::Rect,
            position: Point::ORIGIN,
            size: (Nm::from_mm(0.5), Nm::from_mm(0.5)),
            drill: None,
            layers: vec![Layer::TopCopper],
        };
        assert!(smd.is_smd());
        assert!(!smd.is_through_hole());

        let tht = PadDef {
